print("\nMETHOD INFO")
for cls in [Checkpoint, Tokenizer]:
    print(f"\n===== {cls.__name__} =====")
    for methname in list(getattr(cls, "__dict__", {}).keys()):
        if methname.startswith("__") and methname not in {"__init__", "__call__"}:
            continue
        fn = getattr(cls, methname, None)
        print("\nmethod:", methname, "fn:", fn)
        try:
            print("signature:", inspect.signature(fn))
        except Exception as e:
            print("signature failed:", repr(e))
        try:
            print("doc:", inspect.getdoc(fn))
        except Exception:
            pass
        if hasattr(fn, "__code__"):
            co = fn.__code__
            print("codevars:", co.co_varnames)
            print("freenames:", co.co_freevars, "cellvars:", co.co_cellvars)
            print("fileline:", co.co_filename, co.co_firstlineno)
            try:
                dis.dis(fn)
            except Exception as e:
                print("dis failed:", repr(e))

