import collections, numpy as np
a=Checkpoint("A"); b=Checkpoint("B")
rows=[]
for k in a.keys():
    x=a.get(k); y=b.get(k); d=y-x
    nx=np.linalg.norm(x.ravel())
    ny=np.linalg.norm(y.ravel())
    nd=np.linalg.norm(d.ravel())
    rho=nd/(nx+1e-30)
    if nx: rows.append((rho,k,x.shape,nx,nd))
rows=sorted(rows, reverse=True)[:200]
for rho,k,shape,nx,nd in rows: print(f"{rho:.9f} {k} {shape} normA={nx:.6g} diff={nd:.6g}")
print("top groups")
d=collections.defaultdict(list)
for k in a.keys():
    parts=k.split(".")
    cat=".".join(parts[-2:-1])+"."+parts[-1]
    d[cat].append(k)
for cat,ks in d.items(): print(cat, sum(np.linalg.norm((b.get(k)-a.get(k)).ravel())**2 for k in ks))
